class Solution { public int largestComponentSize(int[] nums){int n=nums.length;int[] parent=new int[n],size=new int[n];for(int i=0;i<n;i++){parent[i]=i;size[i]=1;}Map<Integer,Integer> owner=new HashMap<>();for(int i=0;i<n;i++){int value=nums[i];for(int factor=2;factor*factor<=value;factor++)if(value%factor==0){connect(factor,i,owner,parent,size);while(value%factor==0)value/=factor;}if(value>1)connect(value,i,owner,parent,size);}int answer=0;for(int i=0;i<n;i++)if(find(i,parent)==i)answer=Math.max(answer,size[i]);return answer;}private void connect(int factor,int i,Map<Integer,Integer> owner,int[] p,int[] s){Integer other=owner.putIfAbsent(factor,i);if(other!=null)union(i,other,p,s);}private int find(int x,int[] p){return p[x]==x?x:(p[x]=find(p[x],p));}private void union(int a,int b,int[] p,int[] s){a=find(a,p);b=find(b,p);if(a==b)return;if(s[a]<s[b]){int t=a;a=b;b=t;}p[b]=a;s[a]+=s[b];} }
